declare original_clock jsonb; original_history jsonb;
begin
 select state#>'{tournaments,0,clock}',state#>'{tournaments,1}' into original_clock,original_history from td_consolidated_validation;
 assert (select state#>>'{templates,0,settings,payoutMode}' from td_consolidated_validation)='guaranteed','Saved structure lost its guarantee';
 assert (select state#>>'{clockAppearanceDefaults,timerStyle}' from td_consolidated_validation)='stripes','Preferred clock defaults changed';
 assert (select state#>>'{tournaments,0,payoutCustom}' from td_consolidated_validation)='true','Custom arrangement was not retained';
 assert (select state#>>'{tournaments,0,payoutAutomatic,payoutMode}' from td_consolidated_validation)='guaranteed','Automatic source was lost';
 assert (select state#>>'{tournaments,0,entries,0,eliminationSeat,seat}' from td_consolidated_validation)='1','Original elimination seat was lost';
 assert (select sum(value::bigint) from td_consolidated_validation,jsonb_array_elements_text(state#>'{tournaments,0,settings,payouts}'))=100000,'Custom awards changed';
 update td_consolidated_validation set state=jsonb_set(state,'{tournaments,0,tvDisplayMode}','"full-clock"'::jsonb);
 assert (select state#>'{tournaments,0,clock}' from td_consolidated_validation)=original_clock,'TV change altered the clock';
 assert (select state#>'{tournaments,1}' from td_consolidated_validation)=original_history,'Completed history changed';
end $$;
select 'PASS: guarantee structures, custom funding, clock defaults, elimination seats and completed history survive storage validation' as result;
